<div class="page-wrap"><div class="admin-nav"><a href="<?=e(url('/admin'))?>">Tổng quan</a><a href="<?=e(url('/admin/products'))?>">Sản phẩm</a><a class="active" href="<?=e(url('/admin/containers'))?>">Vòng đời hộp</a><a href="<?=e(url('/admin/locations'))?>">Điểm nhận/trả</a><a href="<?=e(url('/admin/users'))?>">Tài khoản</a><a href="<?=e(url('/admin/reports'))?>">Báo cáo</a></div><h1 class="page-title">Theo dài từng <em>chiếc hộp.</em></h1><div class="admin-card"><h2>Đăng ký hộp vật là và cấp QR</h2><form class="admin-form" method="post" action="<?=e(url('/admin/container/save'))?>"><?=csrf_field()?><label>Loại hộp<select name="product_id"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Điểm lưu kho<select name="location_id"><?php foreach($locations as $l):?><option value="<?=$l['id']?>"><?=e($l['name'])?></option><?php endforeach;?></select></label><label>mã serial tùy chọn<input name="serial_code" placeholder="Bỏ trống để tự tạo"></label><label>Số lượng<input name="quantity" type="number" min="1" max="100" value="1"></label><button class="btn btn-dark">Tạo hộp và QR an toàn</button></form></div><div class="admin-card"><div class="table-wrap"><table><thead><tr><th>SERIAL</th><th>LOẠI HỘP</th><th>ĐIỂM</th><th>TRẠNG thói</th><th>LƯỢT dùng</th><th>TOKEN QR</th></tr></thead><tbody><?php foreach($containers as $c):?><tr><td><?=e($c['serial_code'])?></td><td><?=e($c['product'])?></td><td><?=e($c['location']??'—')?></td><td><span class="status-pill"><?=e($c['lifecycle_status'])?></span></td><td><?=$c['usage_count']?></td><td><code><?=e(substr($c['qr_token'],0,12))?>…</code></td></tr><?php endforeach;?></tbody></table></div></div></div>